40	/*
41	 * Describes a buffer state
42	 * [XXXXXXXXXXXXDATA PAYLOAD       XXXXXXXXXXXXXXXXXXXXXXXX]
43	 * ^            ^                  ^                       ^]
44	 * \_data points\_pos points here  \_used points here |    /
45	 *   here                                          Allocated
46	 */
47	struct ssh_buffer_struct {
48	    bool secure;
49	    size_t used;
50	    size_t allocated;
51	    size_t pos;
52	    uint8_t *data;
53	};
54	
55	/* Buffer size maximum is 256M */
56	#define BUFFER_SIZE_MAX 0x10000000
57	
58	/**
59	 * @defgroup libssh_buffer The SSH buffer functions.
60	 * @ingroup libssh
61	 *
62	 * Functions to handle SSH buffers.
63	 *
64	 * @{
65	 */
