68	#ifdef DEBUG_BUFFER
69	/**
70	 * @internal
71	 *
72	 * @brief Check that preconditions and postconditions are valid.
73	 *
74	 * @param[in]  buf      The buffer to check.
75	 */
76	static void buffer_verify(ssh_buffer buf)
77	{
78	    bool do_abort = false;
79	
80	    if (buf->data == NULL) {
81	        return;
82	    }
83	
84	    if (buf->used > buf->allocated) {
85	        fprintf(stderr,
86	                "BUFFER ERROR: allocated %zu, used %zu\n",
87	                buf->allocated,
88	                buf->used);
89	        do_abort = true;
90	    }
91	    if (buf->pos > buf->used) {
92	        fprintf(stderr,
93	                "BUFFER ERROR: position %zu, used %zu\n",
94	                buf->pos,
95	                buf->used);
96	        do_abort = true;
97	    }
98	    if (buf->pos > buf->allocated) {
99	        fprintf(stderr,
100	                "BUFFER ERROR: position %zu, allocated %zu\n",
101	                buf->pos,
102	                buf->allocated);
103	        do_abort = true;
104	    }
105	    if (do_abort) {
106	        abort();
107	    }
108	}
109	
110	#else
111	#define buffer_verify(x)
112	#endif
