114	/**
115	 * @brief Create a new SSH buffer.
116	 *
117	 * @return A newly initialized SSH buffer, NULL on error.
118	 */
119	struct ssh_buffer_struct *ssh_buffer_new(void)
120	{
121	    struct ssh_buffer_struct *buf = NULL;
122	    int rc;
123	
124	    buf = calloc(1, sizeof(struct ssh_buffer_struct));
125	    if (buf == NULL) {
126	        return NULL;
127	    }
128	
129	    /*
130	     * Always preallocate 64 bytes.
131	     *
132	     * -1 for ralloc_buffer magic.
133	     */
134	    rc = ssh_buffer_allocate_size(buf, 64 - 1);
135	    if (rc != 0) {
136	        SAFE_FREE(buf);
137	        return NULL;
138	    }
139	    buffer_verify(buf);
140	
141	    return buf;
142	}
143	
144	/**
145	 * @brief Deallocate a SSH buffer.
146	 *
147	 * \param[in]  buffer   The buffer to free.
148	 */
149	void ssh_buffer_free(struct ssh_buffer_struct *buffer)
150	{
151	    if (buffer == NULL) {
152	        return;
153	    }
154	    buffer_verify(buffer);
155	
156	    if (buffer->secure && buffer->allocated > 0) {
157	        /* burn the data */
158	        explicit_bzero(buffer->data, buffer->allocated);
159	        SAFE_FREE(buffer->data);
160	
161	        explicit_bzero(buffer, sizeof(struct ssh_buffer_struct));
162	    } else {
163	        SAFE_FREE(buffer->data);
164	    }
165	    SAFE_FREE(buffer);
166	}
