168	/**
169	 * @brief Sets the buffer as secure.
170	 *
171	 * A secure buffer will never leave cleartext data in the heap
172	 * after being reallocated or freed.
173	 *
174	 * @param[in] buffer buffer to set secure.
175	 */
176	void ssh_buffer_set_secure(ssh_buffer buffer)
177	{
178	    buffer->secure = true;
179	}
