249	/**
250	 * @brief Reinitialize a SSH buffer.
251	 *
252	 * In case the buffer has exceeded 64K in size, the buffer will be reallocated
253	 * to 64K.
254	 *
255	 * @param[in]  buffer   The buffer to reinitialize.
256	 *
257	 * @return              0 on success, < 0 on error.
258	 */
259	int ssh_buffer_reinit(struct ssh_buffer_struct *buffer)
260	{
261	    if (buffer == NULL) {
262	        return -1;
263	    }
264	
265	    buffer_verify(buffer);
266	
267	    if (buffer->secure && buffer->allocated > 0) {
268	        explicit_bzero(buffer->data, buffer->allocated);
269	    }
270	    buffer->used = 0;
271	    buffer->pos = 0;
272	
273	    /* If the buffer is bigger then 64K, reset it to 64K */
274	    if (buffer->allocated > 65536) {
275	        int rc;
276	
277	        /* -1 for realloc_buffer magic */
278	        rc = realloc_buffer(buffer, 65536 - 1);
279	        if (rc != 0) {
280	            return -1;
281	        }
282	    }
283	
284	    buffer_verify(buffer);
285	
286	    return 0;
287	}
