326	/**
327	 * @brief Ensure the buffer has at least a certain preallocated size.
328	 *
329	 * @param[in]  buffer   The buffer to enlarge.
330	 *
331	 * @param[in]  len      The length to ensure as allocated.
332	 *
333	 * @return              0 on success, < 0 on error.
334	 */
335	int ssh_buffer_allocate_size(struct ssh_buffer_struct *buffer,
336	                             uint32_t len)
337	{
338	    buffer_verify(buffer);
339	
340	    if (buffer->allocated < len) {
341	        if (buffer->pos > 0) {
342	            buffer_shift(buffer);
343	        }
344	        if (realloc_buffer(buffer, len) < 0) {
345	            return -1;
346	        }
347	    }
348	
349	    buffer_verify(buffer);
350	
351	    return 0;
352	}
