354	/**
355	 * @internal
356	 *
357	 * @brief Allocate space for data at the tail of a buffer.
358	 *
359	 * @param[in]  buffer   The buffer to add the data.
360	 *
361	 * @param[in]  len      The length of the data to add.
362	 *
363	 * @return              Pointer on the allocated space
364	 *                      NULL on error.
365	 */
366	void *ssh_buffer_allocate(struct ssh_buffer_struct *buffer, uint32_t len)
367	{
368	    void *ptr;
369	    buffer_verify(buffer);
370	
371	    if (buffer->used + len < len) {
372	        return NULL;
373	    }
374	
375	    if (buffer->allocated < (buffer->used + len)) {
376	        if (buffer->pos > 0) {
377	            buffer_shift(buffer);
378	        }
379	
380	        if (realloc_buffer(buffer, buffer->used + len) < 0) {
381	            return NULL;
382	        }
383	    }
384	
385	    ptr = buffer->data + buffer->used;
386	    buffer->used+=len;
387	    buffer_verify(buffer);
388	
389	    return ptr;
390	}
