511	/**
512	 * @internal
513	 *
514	 * @brief Add data at the head of a buffer.
515	 *
516	 * @param[in]  buffer   The buffer to add the data.
517	 *
518	 * @param[in]  data     The data to prepend.
519	 *
520	 * @param[in]  len      The length of data to prepend.
521	 *
522	 * @return              0 on success, -1 on error.
523	 */
524	int ssh_buffer_prepend_data(struct ssh_buffer_struct *buffer, const void *data,
525	    uint32_t len) {
526	  buffer_verify(buffer);
527	
528	  if(len <= buffer->pos){
529	    /* It's possible to insert data between begin and pos */
530	    memcpy(buffer->data + (buffer->pos - len), data, len);
531	    buffer->pos -= len;
532	    buffer_verify(buffer);
533	    return 0;
534	  }
535	  /* pos isn't high enough */
536	  if (buffer->used - buffer->pos + len < len) {
537	    return -1;
538	  }
539	
540	  if (buffer->allocated < (buffer->used - buffer->pos + len)) {
541	    if (realloc_buffer(buffer, buffer->used - buffer->pos + len) < 0) {
542	      return -1;
543	    }
544	  }
545	  memmove(buffer->data + len, buffer->data + buffer->pos, buffer->used - buffer->pos);
546	  memcpy(buffer->data, data, len);
547	  buffer->used += len - buffer->pos;
548	  buffer->pos = 0;
549	  buffer_verify(buffer);
550	  return 0;
551	}
