553	/**
554	 * @internal
555	 *
556	 * @brief Append data from a buffer to the tail of another buffer.
557	 *
558	 * @param[in]  buffer   The destination buffer.
559	 *
560	 * @param[in]  source   The source buffer to append. It doesn't take the
561	 *                      position of the buffer into account.
562	 *
563	 * @return              0 on success, -1 on error.
564	 */
565	int ssh_buffer_add_buffer(struct ssh_buffer_struct *buffer,
566	    struct ssh_buffer_struct *source)
567	{
568	    int rc;
569	
570	    rc = ssh_buffer_add_data(buffer,
571	                             ssh_buffer_get(source),
572	                             ssh_buffer_get_len(source));
573	    if (rc < 0) {
574	        return -1;
575	    }
576	
577	    return 0;
