580	/**
581	 * @brief Get a pointer to the head of a buffer at the current position.
582	 *
583	 * @param[in]  buffer   The buffer to get the head pointer.
584	 *
585	 * @return              A pointer to the data from current position.
586	 *
587	 * @see ssh_buffer_get_len()
588	 */
589	void *ssh_buffer_get(struct ssh_buffer_struct *buffer){
590	    return buffer->data + buffer->pos;
591	}
