593	/**
594	 * @brief Get the length of the buffer from the current position.
595	 *
596	 * @param[in]  buffer   The buffer to get the length from.
597	 *
598	 * @return              The length of the buffer.
599	 *
600	 * @see ssh_buffer_get()
601	 */
602	uint32_t ssh_buffer_get_len(struct ssh_buffer_struct *buffer){
603	  buffer_verify(buffer);
604	  return buffer->used - buffer->pos;
605	}
