607	/**
608	 * @internal
609	 *
610	 * @brief Advance the position in the buffer.
611	 *
612	 * This has effect to "eat" bytes at head of the buffer.
613	 *
614	 * @param[in]  buffer   The buffer to advance the position.
615	 *
616	 * @param[in]  len      The number of bytes to eat.
617	 *
618	 * @return              The new size of the buffer.
619	 */
620	uint32_t ssh_buffer_pass_bytes(struct ssh_buffer_struct *buffer, uint32_t len){
621	    buffer_verify(buffer);
622	
623	    if (buffer->pos + len < len || buffer->used < buffer->pos + len) {
624	        return 0;
625	    }
626	
627	    buffer->pos+=len;
628	    /* if the buffer is empty after having passed the whole bytes into it, we can clean it */
629	    if(buffer->pos==buffer->used){
630	        buffer->pos=0;
631	        buffer->used=0;
632	    }
633	    buffer_verify(buffer);
634	    return len;
635	}
