637	/**
638	 * @internal
639	 *
640	 * @brief Cut the end of the buffer.
641	 *
642	 * @param[in]  buffer   The buffer to cut.
643	 *
644	 * @param[in]  len      The number of bytes to remove from the tail.
645	 *
646	 * @return              The new size of the buffer.
647	 */
648	uint32_t ssh_buffer_pass_bytes_end(struct ssh_buffer_struct *buffer, uint32_t len){
649	  buffer_verify(buffer);
650	
651	  if (buffer->used < len) {
652	      return 0;
653	  }
654	
655	  buffer->used-=len;
656	  buffer_verify(buffer);
657	  return len;
658	}
