660	/**
661	 * @brief Get the remaining data out of the buffer and adjust the read pointer.
662	 *
663	 * @param[in]  buffer   The buffer to read.
664	 *
665	 * @param[in]  data     The data buffer where to store the data.
666	 *
667	 * @param[in]  len      The length to read from the buffer.
668	 *
669	 * @returns             0 if there is not enough data in buffer, len otherwise.
670	 */
671	uint32_t ssh_buffer_get_data(struct ssh_buffer_struct *buffer, void *data, uint32_t len)
672	{
673	    int rc;
674	
675	    /*
676	     * Check for a integer overflow first, then check if not enough data is in
677	     * the buffer.
678	     */
679	    rc = ssh_buffer_validate_length(buffer, len);
680	    if (rc != SSH_OK) {
681	        return 0;
682	    }
683	    memcpy(data,buffer->data+buffer->pos,len);
684	    buffer->pos+=len;
685	    return len;   /* no yet support for partial reads (is it really needed ?? ) */
686	}
