734	/**
735	 * @brief Valdiates that the given length can be obtained from the buffer.
736	 *
737	 * @param[in]  buffer  The buffer to read from.
738	 *
739	 * @param[in]  len     The length to be checked.
740	 *
741	 * @return             SSH_OK if the length is valid, SSH_ERROR otherwise.
742	 */
743	int ssh_buffer_validate_length(struct ssh_buffer_struct *buffer, size_t len)
744	{
745	    if (buffer->pos + len < len || buffer->pos + len > buffer->used) {
746	        return SSH_ERROR;
747	    }
748	
749	    return SSH_OK;
750	}
