794	/**
795	 * @brief Pre-calculate the size we need for packing the buffer.
796	 *
797	 * This makes sure that enough memory is allocated for packing the buffer and
798	 * we only have to do one memory allocation.
799	 *
800	 * @param[in]  buffer    The buffer to allocate
801	 *
802	 * @param[in]  format    A format string of arguments.
803	 *
804	 * @param[in]  argc      The number of arguments.
805	 *
806	 * @param[in]  ap        The va_list of arguments.
807	 *
808	 * @return SSH_OK on success, SSH_ERROR on error.
809	 */
810	static int ssh_buffer_pack_allocate_va(struct ssh_buffer_struct *buffer,
811	                                       const char *format,
812	                                       int argc,
813	                                       va_list ap)
814	{
815	    const char *p = NULL;
816	    ssh_string string = NULL;
817	    char *cstring = NULL;
818	    size_t needed_size = 0;
819	    size_t count;
820	    size_t len;
821	    int rc = SSH_OK;
822	
823	    for (p = format, count = 0; *p != '\0'; p++, count++) {
824	        /* Invalid number of arguments passed */
825	        if (argc != -1 && count > argc) {
826	            return SSH_ERROR;
827	        }
828	
829	        switch(*p) {
830	        case 'b':
831	            va_arg(ap, unsigned int);
832	            needed_size += sizeof(uint8_t);
833	            break;
834	        case 'w':
835	            va_arg(ap, unsigned int);
836	            needed_size += sizeof(uint16_t);
837	            break;
838	        case 'd':
839	            va_arg(ap, uint32_t);
840	            needed_size += sizeof(uint32_t);
841	            break;
842	        case 'q':
843	            va_arg(ap, uint64_t);
844	            needed_size += sizeof(uint64_t);
845	            break;
846	        case 'S':
847	            string = va_arg(ap, ssh_string);
848	            needed_size += 4 + ssh_string_len(string);
849	            string = NULL;
850	            break;
851	        case 's':
852	            cstring = va_arg(ap, char *);
853	            needed_size += sizeof(uint32_t) + strlen(cstring);
854	            cstring = NULL;
855	            break;
856	        case 'P':
857	            len = va_arg(ap, size_t);
858	            needed_size += len;
859	            va_arg(ap, void *);
860	            count++; /* increase argument count */
861	            break;
862	        case 'B':
863	            va_arg(ap, bignum);
864	            /*
865	             * Use a fixed size for a bignum
866	             * (they should normaly be around 32)
867	             */
868	            needed_size += 64;
869	            break;
870	        case 't':
871	            cstring = va_arg(ap, char *);
872	            needed_size += strlen(cstring);
873	            cstring = NULL;
874	            break;
875	        default:
876	            SSH_LOG(SSH_LOG_WARN, "Invalid buffer format %c", *p);
877	            rc = SSH_ERROR;
878	        }
879	        if (rc != SSH_OK){
880	            break;
881	        }
882	    }
883	
884	    if (argc != -1 && argc != count) {
885	        return SSH_ERROR;
886	    }
887	
888	    if (rc != SSH_ERROR){
889	        /*
890	         * Check if our canary is intact, if not, something really bad happened.
891	         */
892	        uint32_t canary = va_arg(ap, uint32_t);
893	        if (canary != SSH_BUFFER_PACK_END) {
894	            if (argc == -1){
895	                return SSH_ERROR;
896	            } else {
897	                abort();
898	            }
899	        }
900	    }
901	
902	    rc = ssh_buffer_allocate_size(buffer, needed_size);
903	    if (rc != 0) {
904	        return SSH_ERROR;
905	    }
906	
907	    return SSH_OK;
908	}
