910	/** @internal
911	 * @brief Add multiple values in a buffer on a single function call
912	 * @param[in] buffer    The buffer to add to
913	 * @param[in] format    A format string of arguments.
914	 * @param[in] ap        A va_list of arguments.
915	 * @returns             SSH_OK on success
916	 *                      SSH_ERROR on error
917	 * @see ssh_buffer_add_format() for format list values.
918	 */
919	int ssh_buffer_pack_va(struct ssh_buffer_struct *buffer,
920	                       const char *format,
921	                       int argc,
922	                       va_list ap)
923	{
924	    int rc = SSH_ERROR;
925	    const char *p;
926	    union {
927	        uint8_t byte;
928	        uint16_t word;
929	        uint32_t dword;
930	        uint64_t qword;
931	        ssh_string string;
932	        void *data;
933	    } o;
934	    char *cstring;
935	    bignum b;
936	    size_t len;
937	    int count;
938	
939	    for (p = format, count = 0; *p != '\0'; p++, count++) {
940	        /* Invalid number of arguments passed */
941	        if (argc != -1 && count > argc) {
942	            return SSH_ERROR;
943	        }
944	
945	        switch(*p) {
946	        case 'b':
947	            o.byte = (uint8_t)va_arg(ap, unsigned int);
948	            rc = ssh_buffer_add_u8(buffer, o.byte);
949	            break;
950	        case 'w':
951	            o.word = (uint16_t)va_arg(ap, unsigned int);
952	            o.word = htons(o.word);
953	            rc = ssh_buffer_add_u16(buffer, o.word);
954	            break;
955	        case 'd':
956	            o.dword = va_arg(ap, uint32_t);
957	            o.dword = htonl(o.dword);
958	            rc = ssh_buffer_add_u32(buffer, o.dword);
959	            break;
960	        case 'q':
961	            o.qword = va_arg(ap, uint64_t);
962	            o.qword = htonll(o.qword);
963	            rc = ssh_buffer_add_u64(buffer, o.qword);
964	            break;
965	        case 'S':
966	            o.string = va_arg(ap, ssh_string);
967	            rc = ssh_buffer_add_ssh_string(buffer, o.string);
968	            o.string = NULL;
969	            break;
970	        case 's':
971	            cstring = va_arg(ap, char *);
972	            len = strlen(cstring);
973	            rc = ssh_buffer_add_u32(buffer, htonl(len));
974	            if (rc == SSH_OK){
975	                rc = ssh_buffer_add_data(buffer, cstring, len);
976	            }
977	            cstring = NULL;
978	            break;
979	        case 'P':
980	            len = va_arg(ap, size_t);
981	
982	            o.data = va_arg(ap, void *);
983	            count++; /* increase argument count */
984	
985	            rc = ssh_buffer_add_data(buffer, o.data, len);
986	            o.data = NULL;
987	            break;
988	        case 'B':
989	            b = va_arg(ap, bignum);
990	            o.string = ssh_make_bignum_string(b);
991	            if(o.string == NULL){
992	                rc = SSH_ERROR;
993	                break;
994	            }
995	            rc = ssh_buffer_add_ssh_string(buffer, o.string);
996	            SAFE_FREE(o.string);
997	            break;
998	        case 't':
999	            cstring = va_arg(ap, char *);
1000	            len = strlen(cstring);
1001	            rc = ssh_buffer_add_data(buffer, cstring, len);
1002	            cstring = NULL;
1003	            break;
1004	        default:
1005	            SSH_LOG(SSH_LOG_WARN, "Invalid buffer format %c", *p);
1006	            rc = SSH_ERROR;
1007	        }
1008	        if (rc != SSH_OK){
1009	            break;
1010	        }
1011	    }
1012	
1013	    if (argc != -1 && argc != count) {
1014	        return SSH_ERROR;
1015	    }
1016	
1017	    if (rc != SSH_ERROR){
1018	        /* Check if our canary is intact, if not somthing really bad happened */
1019	        uint32_t canary = va_arg(ap, uint32_t);
1020	        if (canary != SSH_BUFFER_PACK_END) {
1021	            if (argc == -1){
1022	                return SSH_ERROR;
1023	            } else {
1024	                abort();
1025	            }
1026	        }
1027	    }
1028	    return rc;
1029	}
1030	
1031	/** @internal
1032	 * @brief Add multiple values in a buffer on a single function call
1033	 * @param[in] buffer    The buffer to add to
1034	 * @param[in] format    A format string of arguments. This string contains single
1035	 *                      letters describing the order and type of arguments:
1036	 *                         'b': uint8_t  (pushed in network byte order)
1037	 *                         'w': uint16_t (pushed in network byte order)
1038	 *                         'd': uint32_t (pushed in network byte order)
1039	 *                         'q': uint64_t (pushed in network byte order)
1040	 *                         'S': ssh_string
1041	 *                         's': char * (C string, pushed as SSH string)
1042	 *                         't': char * (C string, pushed as free text)
1043	 *                         'P': size_t, void * (len of data, pointer to data)
1044	 *                              only pushes data.
1045	 *                         'B': bignum (pushed as SSH string)
1046	 * @returns             SSH_OK on success
1047	 *                      SSH_ERROR on error
1048	 * @warning             when using 'P' with a constant size (e.g. 8), do not
1049	 *                      forget to cast to (size_t).
1050	 */
1051	int _ssh_buffer_pack(struct ssh_buffer_struct *buffer,
1052	                     const char *format,
1053	                     int argc,
1054	                     ...)
1055	{
1056	    va_list ap;
1057	    int rc;
1058	
1059	    va_start(ap, argc);
1060	    rc = ssh_buffer_pack_allocate_va(buffer, format, argc, ap);
1061	    va_end(ap);
1062	
1063	    if (rc != SSH_OK) {
1064	        return rc;
1065	    }
1066	
1067	    va_start(ap, argc);
1068	    rc = ssh_buffer_pack_va(buffer, format, argc, ap);
1069	    va_end(ap);
1070	
1071	    return rc;
1072	}
1073	
1074	/** @internal
1075	 * @brief Get multiple values from a buffer on a single function call
1076	 * @param[in] buffer    The buffer to get from
1077	 * @param[in] format    A format string of arguments.
1078	 * @param[in] ap        A va_list of arguments.
1079	 * @returns             SSH_OK on success
1080	 *                      SSH_ERROR on error
1081	 * @see ssh_buffer_get_format() for format list values.
1082	 */
1083	int ssh_buffer_unpack_va(struct ssh_buffer_struct *buffer,
1084	                         const char *format,
1085	                         int argc,
1086	                         va_list ap)
1087	{
1088	    int rc = SSH_ERROR;
1089	    const char *p, *last;
1090	    union {
1091	        uint8_t *byte;
1092	        uint16_t *word;
1093	        uint32_t *dword;
1094	        uint64_t *qword;
1095	        ssh_string *string;
1096	        char **cstring;
1097	        void **data;
1098	    } o;
1099	    size_t len, rlen, max_len;
1100	    va_list ap_copy;
1101	    int count;
1102	
1103	    max_len = ssh_buffer_get_len(buffer);
1104	
1105	    /* copy the argument list in case a rollback is needed */
1106	    va_copy(ap_copy, ap);
1107	
1108	    for (p = format, count = 0; *p != '\0'; p++, count++) {
1109	        /* Invalid number of arguments passed */
1110	        if (argc != -1 && count > argc) {
1111	            va_end(ap_copy);
1112	            return SSH_ERROR;
1113	        }
1114	
1115	        switch (*p) {
1116	        case 'b':
1117	            o.byte = va_arg(ap, uint8_t *);
1118	            rlen = ssh_buffer_get_u8(buffer, o.byte);
1119	            rc = rlen==1 ? SSH_OK : SSH_ERROR;
1120	            break;
1121	        case 'w':
1122	            o.word = va_arg(ap,  uint16_t *);
1123	            rlen = ssh_buffer_get_data(buffer, o.word, sizeof(uint16_t));
1124	            *o.word = ntohs(*o.word);
1125	            rc = rlen==2 ? SSH_OK : SSH_ERROR;
1126	            break;
1127	        case 'd':
1128	            o.dword = va_arg(ap, uint32_t *);
1129	            rlen = ssh_buffer_get_u32(buffer, o.dword);
1130	            *o.dword = ntohl(*o.dword);
1131	            rc = rlen==4 ? SSH_OK : SSH_ERROR;
1132	            break;
1133	        case 'q':
1134	            o.qword = va_arg(ap, uint64_t*);
1135	            rlen = ssh_buffer_get_u64(buffer, o.qword);
1136	            *o.qword = ntohll(*o.qword);
1137	            rc = rlen==8 ? SSH_OK : SSH_ERROR;
1138	            break;
1139	        case 'S':
1140	            o.string = va_arg(ap, ssh_string *);
1141	            *o.string = ssh_buffer_get_ssh_string(buffer);
1142	            rc = *o.string != NULL ? SSH_OK : SSH_ERROR;
1143	            o.string = NULL;
1144	            break;
1145	        case 's': {
1146	            uint32_t u32len = 0;
1147	
1148	            o.cstring = va_arg(ap, char **);
1149	            *o.cstring = NULL;
1150	            rc = ssh_buffer_get_u32(buffer, &u32len);
1151	            if (rc != 4){
1152	                rc = SSH_ERROR;
1153	                break;
1154	            }
1155	            len = ntohl(u32len);
1156	            if (len > max_len - 1) {
1157	                rc = SSH_ERROR;
1158	                break;
1159	            }
1160	
1161	            rc = ssh_buffer_validate_length(buffer, len);
1162	            if (rc != SSH_OK) {
1163	                break;
1164	            }
1165	
1166	            *o.cstring = malloc(len + 1);
1167	            if (*o.cstring == NULL){
1168	                rc = SSH_ERROR;
1169	                break;
1170	            }
1171	            rlen = ssh_buffer_get_data(buffer, *o.cstring, len);
1172	            if (rlen != len){
1173	                SAFE_FREE(*o.cstring);
1174	                rc = SSH_ERROR;
1175	                break;
1176	            }
1177	            (*o.cstring)[len] = '\0';
1178	            o.cstring = NULL;
1179	            rc = SSH_OK;
1180	            break;
1181	        }
1182	        case 'P':
1183	            len = va_arg(ap, size_t);
1184	            if (len > max_len - 1) {
1185	                rc = SSH_ERROR;
1186	                break;
1187	            }
1188	
1189	            rc = ssh_buffer_validate_length(buffer, len);
1190	            if (rc != SSH_OK) {
1191	                break;
1192	            }
1193	
1194	            o.data = va_arg(ap, void **);
1195	            count++;
1196	
1197	            *o.data = malloc(len);
1198	            if(*o.data == NULL){
1199	                rc = SSH_ERROR;
1200	                break;
1201	            }
1202	            rlen = ssh_buffer_get_data(buffer, *o.data, len);
1203	            if (rlen != len){
1204	                SAFE_FREE(*o.data);
1205	                rc = SSH_ERROR;
1206	                break;
1207	            }
1208	            o.data = NULL;
1209	            rc = SSH_OK;
1210	            break;
1211	        default:
1212	            SSH_LOG(SSH_LOG_WARN, "Invalid buffer format %c", *p);
1213	            rc = SSH_ERROR;
1214	        }
1215	        if (rc != SSH_OK) {
1216	            break;
1217	        }
1218	    }
1219	
1220	    if (argc != -1 && argc != count) {
1221	        rc = SSH_ERROR;
1222	    }
1223	
1224	    if (rc != SSH_ERROR){
1225	        /* Check if our canary is intact, if not something really bad happened */
1226	        uint32_t canary = va_arg(ap, uint32_t);
1227	        if (canary != SSH_BUFFER_PACK_END){
1228	            if (argc == -1){
1229	                rc = SSH_ERROR;
1230	            } else {
1231	                abort();
1232	            }
1233	        }
1234	    }
1235	
1236	    if (rc != SSH_OK){
1237	        /* Reset the format string and erase everything that was allocated */
1238	        last = p;
1239	        for(p=format;p<last;++p){
1240	            switch(*p){
1241	            case 'b':
1242	                if (buffer->secure) {
1243	                    o.byte = va_arg(ap_copy, uint8_t *);
1244	                    explicit_bzero(o.byte, sizeof(uint8_t));
1245	                    break;
1246	                }
1247	                break;
1248	            case 'w':
1249	                if (buffer->secure) {
1250	                    o.word = va_arg(ap_copy, uint16_t *);
1251	                    explicit_bzero(o.word, sizeof(uint16_t));
1252	                    break;
1253	                }
1254	                break;
1255	            case 'd':
1256	                if (buffer->secure) {
1257	                    o.dword = va_arg(ap_copy, uint32_t *);
1258	                    explicit_bzero(o.dword, sizeof(uint32_t));
1259	                    break;
1260	                }
1261	                break;
1262	            case 'q':
1263	                if (buffer->secure) {
1264	                    o.qword = va_arg(ap_copy, uint64_t *);
1265	                    explicit_bzero(o.qword, sizeof(uint64_t));
1266	                    break;
1267	                }
1268	                break;
1269	            case 'S':
1270	                o.string = va_arg(ap_copy, ssh_string *);
1271	                if (buffer->secure) {
1272	                    ssh_string_burn(*o.string);
1273	                }
1274	                SAFE_FREE(*o.string);
1275	                break;
1276	            case 's':
1277	                o.cstring = va_arg(ap_copy, char **);
1278	                if (buffer->secure) {
1279	                    explicit_bzero(*o.cstring, strlen(*o.cstring));
1280	                }
1281	                SAFE_FREE(*o.cstring);
1282	                break;
1283	            case 'P':
1284	                len = va_arg(ap_copy, size_t);
1285	                o.data = va_arg(ap_copy, void **);
1286	                if (buffer->secure) {
1287	                    explicit_bzero(*o.data, len);
1288	                }
1289	                SAFE_FREE(*o.data);
1290	                break;
1291	            default:
1292	                (void)va_arg(ap_copy, void *);
1293	                break;
1294	            }
1295	        }
1296	    }
1297	    va_end(ap_copy);
1298	
1299	    return rc;
1300	}
1301	
1302	/** @internal
1303	 * @brief Get multiple values from a buffer on a single function call
1304	 * @param[in] buffer    The buffer to get from
1305	 * @param[in] format    A format string of arguments. This string contains single
1306	 *                      letters describing the order and type of arguments:
1307	 *                         'b': uint8_t *  (pulled in network byte order)
1308	 *                         'w': uint16_t * (pulled in network byte order)
1309	 *                         'd': uint32_t * (pulled in network byte order)
1310	 *                         'q': uint64_t * (pulled in network byte order)
1311	 *                         'S': ssh_string *
1312	 *                         's': char ** (C string, pulled as SSH string)
1313	 *                         'P': size_t, void ** (len of data, pointer to data)
1314	 *                              only pulls data.
1315	 * @returns             SSH_OK on success
1316	 *                      SSH_ERROR on error
1317	 * @warning             when using 'P' with a constant size (e.g. 8), do not
1318	 *                      forget to cast to (size_t).
1319	 */
1320	int _ssh_buffer_unpack(struct ssh_buffer_struct *buffer,
1321	                       const char *format,
1322	                       int argc,
1323	                       ...)
1324	{
1325	    va_list ap;
1326	    int rc;
1327	
1328	    va_start(ap, argc);
1329	    rc = ssh_buffer_unpack_va(buffer, format, argc, ap);
1330	    va_end(ap);
1331	    return rc;
1332	}
